type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Expect shape to have exactly two entries [R, C].
    assert!(
        shape.len() == 2,
        "shape must have exactly two dimensions [R, C]"
    );
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    // By assumption, len == r or len == c, and both r, c > 0.
    let mut mat: Matrix<i8> = Vec::with_capacity(r);

    if len == r {
        // Treat `a` as a column vector: broadcast each a[i] across the i-th row.
        for i in 0..r {
            let v = a[i];
            mat.push(vec![v; c]);
        }
    } else {
        // Otherwise, len == c. Treat `a` as a row vector: clone the entire row r times.
        for _ in 0..r {
            mat.push(a.clone());
        }
    }

    mat
}

